import{_ as o,o as a,c as t,a4 as r}from"./chunks/framework.C7iBV1LP.js";const p=JSON.parse('{"title":"Frequently Asked Questions ❓","description":"","frontmatter":{},"headers":[],"relativePath":"reference/faq.md","filePath":"reference/faq.md"}'),n={name:"reference/faq.md"};function s(d,e,i,l,c,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="frequently-asked-questions-❓" tabindex="-1">Frequently Asked Questions ❓ <a class="header-anchor" href="#frequently-asked-questions-❓" aria-label="Permalink to &quot;Frequently Asked Questions ❓&quot;">​</a></h1><p>Common architectural questions and rationale behind Solar&#39;s design decisions.</p><hr><h2 id="🌲-architecture-flake-structure" tabindex="-1">🌲 Architecture &amp; Flake Structure <a class="header-anchor" href="#🌲-architecture-flake-structure" aria-label="Permalink to &quot;🌲 Architecture &amp; Flake Structure&quot;">​</a></h2><h3 id="q-why-not-keep-modules-in-one-flat-directory" tabindex="-1">Q: Why not keep modules in one flat directory? <a class="header-anchor" href="#q-why-not-keep-modules-in-one-flat-directory" aria-label="Permalink to &quot;Q: Why not keep modules in one flat directory?&quot;">​</a></h3><p>A flat directory becomes unmaintainable as configurations scale past 5 machines. Solar’s dendritic tree creates a clear separation between:</p><ul><li>Foundations (<code>core/</code>)</li><li>Platform tools (<code>programs/</code>, <code>platforms/</code>, <code>services/</code>)</li><li>Workflow presets (<code>suites/</code>)</li><li>Concrete machine declarations (<code>hosts/</code>)</li></ul><h3 id="q-how-does-automatic-module-discovery-work" tabindex="-1">Q: How does automatic module discovery work? <a class="header-anchor" href="#q-how-does-automatic-module-discovery-work" aria-label="Permalink to &quot;Q: How does automatic module discovery work?&quot;">​</a></h3><p><code>modules/default.nix</code> recursively scans <code>modules/</code> for <code>.nix</code> files and automatically maps them to typed options under <code>myFeatures.&lt;path&gt;.enable</code>. You never have to manually import new feature files in <code>flake.nix</code>.</p><hr><h2 id="💾-storage-ephemeral-roots" tabindex="-1">💾 Storage &amp; Ephemeral Roots <a class="header-anchor" href="#💾-storage-ephemeral-roots" aria-label="Permalink to &quot;💾 Storage &amp; Ephemeral Roots&quot;">​</a></h2><h3 id="q-what-is-wipe-on-boot-ephemeral-root" tabindex="-1">Q: What is &quot;wipe-on-boot&quot; (ephemeral root)? <a class="header-anchor" href="#q-what-is-wipe-on-boot-ephemeral-root" aria-label="Permalink to &quot;Q: What is &quot;wipe-on-boot&quot; (ephemeral root)?&quot;">​</a></h3><p>On hosts like <strong><code>mars</code></strong>, <strong><code>mercury</code></strong>, and the <strong>Pluto Cluster</strong>, the root filesystem (<code>/</code>) is mounted in RAM (<code>tmpfs</code>) or wiped on every boot. Only directories explicitly declared in <code>preservation</code> (such as <code>.config</code>, <code>.local/share</code>, <code>/etc/nixos</code>, and <code>/var/log</code>) survive reboots on the NVMe <code>/persist</code> subvolume. This prevents filesystem rot, stale cache buildup, and accidental unmanaged state.</p><h3 id="q-how-do-i-preserve-a-new-application-s-state-on-an-ephemeral-host" tabindex="-1">Q: How do I preserve a new application&#39;s state on an ephemeral host? <a class="header-anchor" href="#q-how-do-i-preserve-a-new-application-s-state-on-an-ephemeral-host" aria-label="Permalink to &quot;Q: How do I preserve a new application&#39;s state on an ephemeral host?&quot;">​</a></h3><p>Declare it in the module&#39;s <code>preservation.preserveAt</code> list, or place the directory under <code>/persist/home/apollo/</code> and symlink it to your home folder.</p><hr><h2 id="🍏-macos-darwin-integration" tabindex="-1">🍏 macOS Darwin Integration <a class="header-anchor" href="#🍏-macos-darwin-integration" aria-label="Permalink to &quot;🍏 macOS Darwin Integration&quot;">​</a></h2><h3 id="q-how-does-solar-manage-both-nixos-and-macos-in-the-same-flake" tabindex="-1">Q: How does Solar manage both NixOS and macOS in the same flake? <a class="header-anchor" href="#q-how-does-solar-manage-both-nixos-and-macos-in-the-same-flake" aria-label="Permalink to &quot;Q: How does Solar manage both NixOS and macOS in the same flake?&quot;">​</a></h3><p><code>flake.nix</code> exports both <code>nixosConfigurations</code> (for Linux hosts) and <code>darwinConfigurations</code> (for macOS hosts like <strong><code>phobos</code></strong>). The module autoscanner (<code>modules/default.nix</code>) uses platform reflection to load <code>modules/darwin/</code> and modules with <code>isDarwin</code> or <code>isTotal</code> on macOS while excluding Linux-only kernel and driver modules.</p><hr><h2 id="🪐-the-fleet-pluto-cluster" tabindex="-1">🪐 The Fleet &amp; Pluto Cluster <a class="header-anchor" href="#🪐-the-fleet-pluto-cluster" aria-label="Permalink to &quot;🪐 The Fleet &amp; Pluto Cluster&quot;">​</a></h2><h3 id="q-why-run-k3s-as-an-ha-cluster-on-mini-pcs-and-laptops" tabindex="-1">Q: Why run K3s as an HA cluster on mini-PCs and laptops? <a class="header-anchor" href="#q-why-run-k3s-as-an-ha-cluster-on-mini-pcs-and-laptops" aria-label="Permalink to &quot;Q: Why run K3s as an HA cluster on mini-PCs and laptops?&quot;">​</a></h3><p>The Pluto Cluster provides a resilient, zero-single-point-of-failure GitOps platform for self-hosted services (Jellyfin, Home Assistant, Minecraft). By using three heterogeneous physical nodes with an embedded etcd quorum, individual nodes can reboot for system updates without service downtime.</p><h3 id="q-why-are-ganymede-and-callisto-deprecated" tabindex="-1">Q: Why are Ganymede and Callisto deprecated? <a class="header-anchor" href="#q-why-are-ganymede-and-callisto-deprecated" aria-label="Permalink to &quot;Q: Why are Ganymede and Callisto deprecated?&quot;">​</a></h3><p>Legacy storage nodes <code>ganymede</code> and <code>callisto</code> were retired in favor of <strong><code>sol</code></strong> (Central ZFS NAS with multi-terabyte mirrored storage and NFS exports) and dynamic Kubernetes persistent volumes managed by the Pluto Cluster.</p><h3 id="q-why-is-luks-encryption-not-enabled-on-the-servers-and-pluto-nodes-by-default" tabindex="-1">Q: Why is LUKS encryption not enabled on the servers and Pluto nodes by default? <a class="header-anchor" href="#q-why-is-luks-encryption-not-enabled-on-the-servers-and-pluto-nodes-by-default" aria-label="Permalink to &quot;Q: Why is LUKS encryption not enabled on the servers and Pluto nodes by default?&quot;">​</a></h3><p>Workstations and laptops (<code>mars</code>, <code>mercury</code>) have <code>enableLuks = true</code> because they are personal or portable devices with a high risk of theft or loss.</p><p>On headless servers and cluster nodes (<code>pluto</code>, <code>styx</code>, <code>hydra</code>, <code>sol</code>), LUKS is disabled by default for operational availability:</p><ol><li><strong>Unattended Automated Reboots</strong>: Pluto nodes perform staggered rolling weekly maintenance reboots (Sunday 03:00, 03:30, 04:00 UTC) to apply updates while maintaining the 2/3 etcd quorum. A manual passphrase prompt blocks early boot (<code>initrd</code>), keeping the node offline after unexpected power cuts or kernel updates.</li><li><strong>Ephemeral In-Memory Root (<code>tmpfs</code>)</strong>: Cluster nodes boot into RAM (<code>/</code> on <code>tmpfs</code>). No application secrets or root filesystem state reside on the local disk.</li><li><strong>Encrypted Secrets at Rest</strong>: Agenix secrets (<code>*.age</code>) are encrypted using asymmetric Age keys and decrypted directly into RAM (<code>/run/agenix/</code>) on boot.</li></ol><p><em>Note: For environments requiring physical disk encryption on stationary nodes, ThinkCentre M920q/M720q nodes support sealing LUKS keys to their discrete <strong>TPM 2.0 (PCR 0+7)</strong> using <code>systemd-cryptenroll</code>, enabling tamper-proof automated unlocking without human intervention.</em></p>',30)])])}const m=o(n,[["render",s]]);export{p as __pageData,m as default};
